#include <utility>

// Afterwards, a is not greater than b.
template <typename T>
void orderTwo(T& a, T& b)
{
    if (b < a)
    {
        using std::swap;
        swap(a, b);
    }
}

unitTests:
namespace shop {
    struct Crate { int weight{}; static inline int customSwaps{ 0 }; friend bool operator<(const Crate& a, const Crate& b) { return a.weight < b.weight; } };
    void swap(Crate& a, Crate& b) noexcept { ++Crate::customSwaps; const int t{ a.weight }; a.weight = b.weight; b.weight = t; }
}

TEST("built-in types fall back to std::swap") { int a{ 9 }; int b{ 4 }; orderTwo(a, b); CHECK_EQ(a, 4); CHECK_EQ(b, 9); orderTwo(a, b); CHECK_EQ(a, 4); std::string s{ "pear" }; std::string t{ "apple" }; orderTwo(s, t); CHECK_EQ(s, "apple"); }
TEST("a type's own swap is found and used") { shop::Crate heavy{ 80 }; shop::Crate light{ 5 }; shop::Crate::customSwaps = 0; orderTwo(heavy, light); CHECK_EQ(heavy.weight, 5); CHECK_EQ(light.weight, 80); CHECK_EQ(shop::Crate::customSwaps, 1); orderTwo(heavy, light); CHECK_EQ(shop::Crate::customSwaps, 1); }

